<template lang="pug">
.page-container
    .page-title 個案列表
    DataTable(ref="table" :fetch-fn="fetchPage" search-placeholder="搜尋姓名／學號")
        template(#toolbar)
            select.labelSelector(v-model='semester_label' @change="onSemesterChange")
                option(value='') 全部學期
                option(v-for='option in labelOption' :key='option.label' :value='option.label') {{ option.label }}
        el-table-column(prop="name" label="姓名")
        el-table-column(prop="caseId" label="學號")
        el-table-column(prop="semester_label" label="學期標籤")
            template(#default='scope')
                SemesterLabelTag(:label="scope.row.semester_label")
        el-table-column(prop="available_time" label="可諮商時段")
            template(#header='')
                el-popover(placement="right" title="" :width="200" trigger="hover" popper-class="weektimePop")
                    div(v-html="getHtmlContent()")
                    template(#reference)
                        span 可諮商時段
                            QuestionFilled(style="width: 1em; height: 1em; padding: 0 0 0 3px")
            template(#default='scope')
                div {{scope.row.available_time}}
        el-table-column(prop="crisis_level" label="危機程度" sortable="custom")
        el-table-column(label="希望性別" width="80")
            template(#default='scope')
                div {{scope.row.preferred_gender || '不限'}}
        el-table-column(label="可派實習生" width="90")
            template(#default='scope')
                div {{internDispatchable(scope.row) ? '可' : '不可'}}
        el-table-column(label="指定心理師" width="90")
            template(#default='scope')
                div {{scope.row.designated_counselor_name || '—'}}
        el-table-column(prop="init_counselor_name" label="初談老師")
        el-table-column(prop="discription" label="狀態說明")
        el-table-column(prop="init_consultation_date" label="初談時間" sortable="custom")
            template(#default='scope')
                div {{convertUTCtoStr(scope.row.init_consultation_date)}}
        el-table-column(label="功能按鈕" align="center" width="150" fixed="right")
            template(v-slot:default="slotProps")
                .cell-actions
                    el-button(type="primary" size="small"  @click="modifyCase(slotProps.row.id)") 修改
                    el-button(type="danger" size="small" @click="clickDelete(slotProps.row)") 刪除
</template>

<script>
import {weektimeMixin} from "@/components/weektimeMixin"
import { isEligible, EMPLOYMENT } from '@/utils/matchingRules'
import SemesterLabelTag from '@/components/SemesterLabelTag.vue';
import DataTable from '@/components/DataTable.vue';
export default {
    components: {SemesterLabelTag, DataTable},
    mixins: [weektimeMixin],
    data () {
        return {
            semester_label: '',
            labelOption: []
        }
    },
    async created() {
        await this.$store.dispatch('fetchSemesterLabel')
        this.labelOption = this.$store.state.semester_label.data
    },
    methods: {
        internDispatchable(row) {
            return isEligible(row, EMPLOYMENT.INTERN)
        },
        async fetchPage({ page, pageSize, q, sort, order }) {
            const params = { status: 'unassign', page, pageSize, q, sort, order }
            if (this.semester_label) params.semester_label = this.semester_label
            const res = await this.$http.get('/api/cases', { params })
            return { data: res.data.data, meta: res.data.meta }
        },
        onSemesterChange() {
            if (this.$refs.table) this.$refs.table.reload(true)
        },
        deleteCase(id) {
            this.$store.commit('SET_STATUS', 'pending')
            this.$http.delete("/api/cases/"+id)
            .then(() => {
                this.$message({
                    type: 'success',
                    message: '刪除成功!'
                });
                this.$refs.table.reload()
                this.$store.commit('SET_STATUS', 'end')
            })
            .catch((error) => {
                console.error(error)
            });
        },
        clickDelete(caseData) {
            this.$confirm('將永久刪除學號為 '+caseData.caseId+' 的資料, 是否繼續?', '提示', {
                confirmButtonText: '確定',
                cancelButtonText: '取消',
                type: 'warning'
                }).then(() => {
                    this.deleteCase(caseData.id)
                }).catch(() => {
                this.$message({
                    type: 'info',
                    message: '已取消刪除'
                })
            })
        },
        modifyCase(id) {
            this.$router.push('/modifyCase/'+id)
        }
    }
}
</script>
<style>
.weektimePop {
    padding: 10px !important;
    background-color: #F0F2F5 !important;
    border-color: #F0F2F5 !important;
    color: #303133 !important;
}
.weektimePop .el-popper__arrow::before {
    border-top-color: #F0F2F5 !important;
    border-color: #F0F2F5 !important;
    background-color: #F0F2F5 !important;
}
.weektimePop > div > table {
    border: 0;
    border-collapse: collapse;
    width: 100%;
    margin: 10px 0;
}
.weektimePop > div > table > tbody > tr > td {
    border: 1px #909399 solid !important;
    padding: 5px 10px;
}
</style>
